30	/*
31	 * RP2040 PL011 instance.
32	 *
33	 * The ST targets carry six USARTs with several pin choices each, so their
34	 * table records a port, a pin, an APB divisor, and an alternate function.
35	 * Here each UART has one pin pair in use and the peripheral clock is common,
36	 * so the table records the register base, the two pins, and the interrupt.
37	 */
38	struct uart_inst {
39	    u_int	base;		/* PL011 register base. */
40	    u_char	tx_gpio;
41	    u_char	rx_gpio;
42	    u_char	irq;		/* NVIC interrupt number. */
43	};
44	
45	/* Pin function 2 selects a UART on every pin the Pico brings out. */
46	#define GPIO_FUNC_UART	2
47	
48	/* RP2040 datasheet section 2.3.2, interrupt table. */
49	#define UART0_IRQ	20
50	#define UART1_IRQ	21
51	
52	static const struct uart_inst uart[NUART] = {
53	    /* UART0 on GP0 and GP1, the pair the Pico exposes on pins 1 and 2. */
54	    { UART0_BASE, 0, 1, UART0_IRQ },
55	    /* UART1 on GP4 and GP5. */
56	    { UART1_BASE, 4, 5, UART1_IRQ },
57	};
