59	/*
60	 * Reset controller and pin multiplexing, RP2040 datasheet sections 2.14 and
61	 * 2.19. Every peripheral leaves reset held, so a driver releases its own
62	 * block and waits for the acknowledgement before touching a register.
63	 */
64	#define RESETS_BASE	0x4000c000UL
65	#define RESETS_RESET	0x0
66	#define RESETS_DONE	0x8
67	#define RESETS_CLR	0x3000		/* Atomic clear alias. */
68	
69	#define RESETS_IO_BANK0		(1UL << 5)
70	#define RESETS_PADS_BANK0	(1UL << 8)
71	#define RESETS_UART0		(1UL << 22)
72	#define RESETS_UART1		(1UL << 23)
73	
74	#define IO_BANK0_BASE	0x40014000UL
75	#define IO_BANK0_CTRL(n)	(0x004 + 8 * (n))
76	
77	#define PADS_BANK0_BASE	0x4001c000UL
78	#define PADS_BANK0_GPIO(n)	(0x04 + 4 * (n))
79	#define PADS_IE			(1UL << 6)	/* Input enable. */
80	#define PADS_OD			(1UL << 7)	/* Output disable. */
81	
82	#define REG32(a)	(*(volatile u_int *)(a))
83	
84	static void
85	uart_unreset(u_int mask)
86	{
87	    REG32(RESETS_BASE + RESETS_CLR + RESETS_RESET) = mask;
88	    while ((REG32(RESETS_BASE + RESETS_DONE) & mask) != mask)
89		continue;
90	}
91	
92	static void
93	uart_pin_setup(u_int gpio)
94	{
95	    /* Drive the pad from the peripheral, and let it read back. */
96	    REG32(PADS_BANK0_BASE + PADS_BANK0_GPIO(gpio)) =
97		(REG32(PADS_BANK0_BASE + PADS_BANK0_GPIO(gpio)) & ~PADS_OD) | PADS_IE;
98	    REG32(IO_BANK0_BASE + IO_BANK0_CTRL(gpio)) = GPIO_FUNC_UART;
99	}
