101	/*
102	 * Set the PL011 divisors. The part divides the peripheral clock by sixteen
103	 * times the baud rate, keeping the integer part in IBRD and sixty-fourths of
104	 * the remainder in FBRD, so the division is carried out in one step at
105	 * 64/16 scale to avoid losing the fraction.
106	 */
107	static void
108	uart_set_baud(u_int base, u_int baud)
109	{
110	    u_int div, ibrd, fbrd;
111	
112	    div = (4 * (BUS_KHZ * 1000)) / baud;	/* 64/16 == 4 */
113	    ibrd = div >> 6;
114	    fbrd = div & 0x3f;
115	
116	    if (ibrd == 0) {
117		ibrd = 1;
118		fbrd = 0;
119	    } else if (ibrd >= 65535) {
120		ibrd = 65535;
121		fbrd = 0;
122	    }
123	
124	    REG32(base + UART_IBRD) = ibrd;
125	    REG32(base + UART_FBRD) = fbrd;
126	    /* Writing LCR_H latches the divisors. */
127	    REG32(base + UART_LCR_H) = UART_LCR_H_WLEN_8 | UART_LCR_H_FEN;
128	}
