130	void
131	uartinit(int unit)
132	{
133	    register const struct uart_inst *uip;
134	
135	    if (unit < 0 || unit >= NUART)
136		return;
137	
138	    uip = &uart[unit];
139	
140	    uart_unreset(RESETS_IO_BANK0 | RESETS_PADS_BANK0);
141	    uart_unreset(unit == 0 ? RESETS_UART0 : RESETS_UART1);
142	
143	    uart_disable(uip->base);
144	
145	    uart_set_baud(uip->base, UART_BAUD);
146	    uart_pin_setup(uip->tx_gpio);
147	    uart_pin_setup(uip->rx_gpio);
148	
149	    /* Start from a clean slate: mask and acknowledge everything. */
150	    uart_irq_disable(uip->base, UART_INT_ALL);
151	    uart_irq_clear(uip->base, UART_INT_ALL);
152	
153	    arm_intr_set_priority(uip->irq, IPL_TTY);
154	
155	    /*
156	     * The receive interrupt is left masked here and unmasked in uartopen
157	     * when a process opens the line. Enabling it at boot would storm the
158	     * handler with framing noise from a floating GP0/GP1 on a board that
159	     * uses the USB console and never wires the UART, starving the console.
160	     */
161	    uart_enable(uip->base);
162	}
