183	int
184	uartopen(dev_t dev, int flag __unused, int mode __unused)
185	{
186	    register const struct uart_inst *uip;
187	    register struct tty *tp;
188	    register int unit = minor(dev);
189	
190	    if (unit < 0 || unit >= NUART)
191	        return (ENXIO);
192	
193	    tp = &uartttys[unit];
194	    if (! tp->t_addr)
195	        return (ENXIO);
196	
197	    uip = (struct uart_inst *)tp->t_addr;
198	    tp->t_oproc = uartstart;
199	    if ((tp->t_state & TS_ISOPEN) == 0) {
200	        if (tp->t_ispeed == 0) {
201	            tp->t_ispeed = BBAUD(UART_BAUD);
202	            tp->t_ospeed = BBAUD(UART_BAUD);
203	        }
204	        ttychars(tp);
205	        tp->t_state = TS_ISOPEN | TS_CARR_ON;
206	        tp->t_flags = ECHO | XTABS | CRMOD | CRTBS | CRTERA | CTLECH | CRTKIL;
207	        /* A serial line carries no window size; open at 80x24, which
208	         * resize(1) then syncs to the terminal's real size. */
209	        tp->t_winsize.ws_row = 24;
210	        tp->t_winsize.ws_col = 80;
211	    }
212	    if ((tp->t_state & TS_XCLUDE) && u.u_uid != 0)
213	        return (EBUSY);
214	
215	    /*
216	     * uartinit has already set the divisors and line format from the
217	     * compile-time baud, so opening the line re-enables the transmitter and
218	     * receiver and unmasks receive and receive-timeout.
219	     */
220	    uart_enable(uip->base);
221	    /* PL011 raises RX past the FIFO trigger level and the timeout when a
222	     * partial FIFO sits idle, so the pair catches a burst and a lone key;
223	     * the NVIC line is enabled here rather than at boot. */
224	    arm_intr_enable_irq(uip->irq);
225	    uart_irq_enable(uip->base, UART_INT_RX | UART_INT_RT);
226	
227	    return ttyopen(dev, tp);
228	}
