300	void
301	uartintr(dev_t dev)
302	{
303	    register int c;
304	    register int unit = minor(dev);
305	    register struct tty *tp = &uartttys[unit];
306	    register const struct uart_inst *uip;
307	
308	    if (! tp->t_addr)
309	        return;
310	
311	    uip = (struct uart_inst *)tp->t_addr;
312	
313	    /* Receive: drain the FIFO while UARTFR reports it non-empty. */
314	    while (uart_rx_ready(uip->base)) {
315	        c = uart_rx_get(uip->base);
316	        ttyinput(c, tp);
317	    }
318	
319	    /*
320	     * Acknowledge the receive sources through UARTICR. Draining the FIFO
321	     * drops the RX level interrupt, but PL011 holds the receive-timeout
322	     * latched until an explicit clear, so the write is what lets a lone
323	     * keystroke raise the next interrupt.
324	     */
325	    uart_irq_clear(uip->base, UART_INT_RX | UART_INT_RT);
326	
327	    /* Transmit */
328	    if (uart_tx_ready(uip->base)) {
329	        led_control(LED_TTY, 0);
330	
331	        /* Disable transmit interrupt. */
332	        uart_irq_disable(uip->base, UART_INT_TX);
333	
334	        if (tp->t_state & TS_BUSY) {
335	            tp->t_state &= ~TS_BUSY;
336	            ttstart(tp);
337	        }
338	    }
339	}
