341	/*
342	 * Start (restart) transmission on the given line.
343	 */
344	void
345	uartstart(struct tty *tp)
346	{
347	    register const struct uart_inst *uip;
348	    register int c, s;
349	
350	    if (! tp->t_addr)
351	        return;
352	
353	    uip = (struct uart_inst *)tp->t_addr;
354	
355	    /*
356	     * Must hold interrupts in following code to prevent
357	     * state of the tp from changing.
358	     */
359	    s = spltty();
360	    /*
361	     * If it is currently active, or delaying, no need to do anything.
362	     */
363	    if (tp->t_state & (TS_TIMEOUT | TS_BUSY | TS_TTSTOP)) {
364	out:
365	        led_control(LED_TTY, 0);
366	        splx(s);
367	        return;
368	    }
369	
370	    /*
371	     * Wake up any sleepers.
372	     */
373	    ttyowake(tp);
374	
375	    /*
376	     * Now restart transmission unless the output queue is empty.
377	     */
378	    if (tp->t_outq.c_cc == 0)
379	        goto out;
380	
381	    if (uart_tx_ready(uip->base)) {
382	        c = getc(&tp->t_outq);
383	        uart_tx_put(uip->base, c & 0xff);
384	        tp->t_state |= TS_BUSY;
385	    }
386	
387	    /* Enable transmit interrupt. */
388	    uart_irq_enable(uip->base, UART_INT_TX);
389	
390	    led_control(LED_TTY, 1);
391	    splx(s);
392	}
