394	void
395	uartputc(dev_t dev, char c)
396	{
397	    int unit = minor(dev);
398	    struct tty *tp = &uartttys[unit];
399	    register const struct uart_inst *uip = &uart[unit];
400	    register int s, timo;
401	
402	    s = spltty();
403	again:
404	    /*
405	     * Try waiting for the console tty to come ready,
406	     * otherwise give up after a reasonable time.
407	     */
408	    timo = 30000;
409	    while (!uart_tx_ready(uip->base))
410	        if (--timo == 0)
411	            break;
412	
413	    if (tp->t_state & TS_BUSY) {
414	        uartintr(dev);
415	        goto again;
416	    }
417	    led_control(LED_TTY, 1);
418	    uart_tx_put(uip->base, c);
419	
420	    timo = 30000;
421	    while (!uart_tx_idle(uip->base))
422	        if (--timo == 0)
423	            break;
424	
425	    led_control(LED_TTY, 0);
426	    splx(s);
427	}
