429	char
430	uartgetc(dev_t dev)
431	{
432	    int unit = minor(dev);
433	    register const struct uart_inst *uip = &uart[unit];
434	    int s, c;
435	
436	    s = spltty();
437	    for (;;) {
438	        /* Wait for key pressed. */
439	        if (uart_rx_ready(uip->base)) {
440	            c = uart_rx_get(uip->base);
441	            break;
442	        }
443	    }
444	
445	    splx(s);
446	    return (unsigned char) c;
447	}
