449	/*
450	 * Test to see if device is present.
451	 * Return true if found and initialized ok.
452	 */
453	static int
454	uartprobe(struct conf_device *config)
455	{
456	    /*
457	     * The RP2040's blocks are UART0 and UART1 and uart[] is indexed the
458	     * same way, so "device uart0" in the configuration names index 0. The
459	     * ST ports count their USARTs from one and subtract here; carrying that
460	     * subtraction over left every unit one below its own index, so unit 0
461	     * failed the range test below and the line never attached.
462	     */
463	    int unit = config->dev_unit;
464	    int is_console = (CONS_MAJOR == UART_MAJOR &&
465	                      CONS_MINOR == unit);
466	
467	    if (unit < 0 || unit >= NUART)
468	        return 0;
469	
470	    /*
471	     * The ST targets name a port letter, a pin number, and an alternate
472	     * function. Every RP2040 pin is GPIO n and the UART is always function
473	     * 2, so the line reports the pin pair alone.
474	     */
475	    printf("uart%d: pins tx=GP%d/rx=GP%d", unit,
476	        uart[unit].tx_gpio, uart[unit].rx_gpio);
477	
478	    if (is_console)
479	        printf(", console");
480	    printf("\n");
481	
482	    /* Initialize the device. */
483	    uartttys[unit].t_addr = (caddr_t) &uart[unit];
484	    if (! is_console)
485	        uartinit(unit);
486	
487	    return 1;
488	}
